INSERT INTO temp_import_pages VALUES ('{"pageId": "c0220000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "sourceShowsPrintedPageLabel": true, "printedPageLabel": "22", "printedPageNumber": 22, "pdfPageNumber": 405, "sequenceIndex": 12, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true, "provenanceNotes": "Canonical transcription checked against the rendered secondary scan; master PDF page mapping retained. Fine vocalisation is preserved where clearly legible; no unresolved Arabic word or letter remains. English OCR correction and Arabic/translation-pair classification pass compared against the rendered source scan; raw OCR retained unchanged."}, "structuralNodes": [{"id": "a6000000-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "PART I", "sourceIdentifier": "I", "title": "IMPORTANCE OF SALAAT", "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "a6100000-0000-4000-8000-000000000001", "parentId": "a6000000-0000-4000-8000-000000000001", "nodeType": "chapter", "sourceLabel": "CHAPTER I", "sourceIdentifier": "I", "title": "THE REWARDS OF SALAAT", "sequenceIndex": 1, "startPageId": null, "endPageId": null}, {"id": "a6200000-0000-4000-8000-000000000008", "parentId": "a6100000-0000-4000-8000-000000000001", "nodeType": "hadith", "sourceLabel": "Hadith.—VII", "sourceIdentifier": "VII", "title": null, "sequenceIndex": 2, "startPageId": null, "endPageId": null}], "blocks": [{"id": "d0220000-0000-4000-8000-000000000001", "structuralNodeId": "a6200000-0000-4000-8000-000000000008", "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Imam Abu Haneefa (Rahmatullah alaih) that he could tell from the water falling down from the limbs of the person performing wudhu as to which sins had been washed off therewith. In a narration by Hadhrat Uthman (Radhiyallaho anho), the Holy Prophet (Sallallaho alaihe wasallam) is reported to have warned against being wrong-headed in committing sins in the hope of getting them redeemed through salaat. We have, really, no ground to behave as such on this account. After all, what is the quality of the salaat that we offer? If Allah merely absolves us of our obligation it is His very special favour and grace. Again it is the height of ingratitude to disobey Allah just because He is Clement, Merciful and Forgiving.", "rawOcrText": "22 Virtues of Salaat Imam Abu Haneefa (Rahmatullah alaih) that he could tell from the water falling down from the limbs of the person peRorming wudhu as to which sins had been washed off therewith. In a narration by Hadhrat Uthman (Radhiyallaho anho), the Holy Prophet (Sallallaho alaihe wasallam) is re- ported to have warned against being wrong-headed in come mitting sins in the hope of getting them redeemed thröugh salaat. We have, really, no ground to behavm as such on this account. After all, what is the quality of the salaat that we offer? If Allah merely absolves us of our obligation it is His very special favour and gace. Again it is .the height of ing•atitude to disobey Allah just because He is Clement, Merciful and Forgiving. Hadith—VII Hadhrat Abu Hurairah (Radhiyallaho anho) narrates, \"Two persons of one clan came to Prophet (Sallallaho alaihe wasallam) embraced Islam at one and the same time. One of these was martyred in a battle and the other died a year later, Hadhrat Talha bin Ubaidul- lah (Radhiyallaho anho) says that he saw in his dream that the person who had died later was admitted into Paradise before .the martyr. This surprised him. I do not •recollect whether it was he .or somebody else who narrated this dream. The Prophet (Sallallaho alaihe wasallam) thereupon remarked: \"Has not the person dying later fasted for one additional month of Rama- dhaan, and has he not offered six thousand or odd ra- kaats of salaat more during the year he lived after the Really, we do not know how valuable salaat is! The Holy Prophet (Sallallaho alaihe wasallam) was often heard", "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0220000-0000-4000-8000-000000000002", "structuralNodeId": "a6200000-0000-4000-8000-000000000008", "sequenceIndex": 1, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith.—VII", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0220000-0000-4000-8000-000000000003", "structuralNodeId": "a6200000-0000-4000-8000-000000000008", "sequenceIndex": 2, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ كَانَ رَجُلَانِ مِنْ بَلِيٍّ حَيٍّ مِنْ قُضَاعَةَ أَسْلَمَا مَعَ رَسُولِ اللَّهِ ﷺ فَاسْتُشْهِدَ أَحَدُهُمَا وَأُخِّرَ الْآخَرُ سَنَةً قَالَ طَلْحَةُ بْنُ عُبَيْدِ اللَّهِ فَرَأَيْتُ الْمُؤَخَّرَ مِنْهُمَا أُدْخِلَ الْجَنَّةَ قَبْلَ الشَّهِيدِ فَتَعَجَّبْتُ لِذَلِكَ فَأَصْبَحْتُ فَذَكَرْتُ ذَلِكَ لِلنَّبِيِّ ﷺ أَوْ ذُكِرَ لِرَسُولِ اللَّهِ ﷺ فَقَالَ رَسُولُ اللَّهِ أَلَيْسَ قَدْ صَامَ بَعْدَهُ رَمَضَانَ وَصَلَّى سِتَّةَ آلَافِ رَكْعَةٍ وَكَذَا وَكَذَا رَكْعَةً صَلَاةَ سَنَةٍ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0220000-0000-4000-8000-000000000004", "structuralNodeId": "a6200000-0000-4000-8000-000000000008", "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "رواه أحمد بإسناد حسن ورواه ابن ماجه", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0220000-0000-4000-8000-000000000005", "structuralNodeId": "a6200000-0000-4000-8000-000000000008", "sequenceIndex": 4, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Abu Hurairah (Radhiyallaho anho) narrates, \"Two persons of one clan came to Prophet (Sallallaho alaihe wasallam) embraced Islam at one and the same time. One of these was martyred in a battle and the other died a year later, Hadhrat Talha bin Ubaidullah (Radhiyallaho anho) says that he saw in his dream that the person who had died later was admitted into Paradise before the martyr. This surprised him. I do not recollect whether it was he or somebody else who narrated this dream. The Prophet (Sallallaho alaihe wasallam) thereupon remarked: \"Has not the person dying later fasted for one additional month of Ramadhaan, and has he not offered six thousand or odd rakaats of salaat more during the year he lived after the Really, we do not know how valuable salaat is! The Holy Prophet (Sallallaho alaihe wasallam) was often heard", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}], "pageNumber": 22}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "c0230000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "sourceShowsPrintedPageLabel": true, "printedPageLabel": "23", "printedPageNumber": 23, "pdfPageNumber": 406, "sequenceIndex": 13, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true, "provenanceNotes": "Canonical transcription checked against the rendered secondary scan; master PDF page mapping retained. Fine vocalisation is preserved where clearly legible; no unresolved Arabic word or letter remains. English OCR correction and Arabic/translation-pair classification pass compared against the rendered source scan; raw OCR retained unchanged."}, "structuralNodes": [{"id": "a6000000-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "PART I", "sourceIdentifier": "I", "title": "IMPORTANCE OF SALAAT", "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "a6100000-0000-4000-8000-000000000001", "parentId": "a6000000-0000-4000-8000-000000000001", "nodeType": "chapter", "sourceLabel": "CHAPTER I", "sourceIdentifier": "I", "title": "THE REWARDS OF SALAAT", "sequenceIndex": 1, "startPageId": null, "endPageId": null}, {"id": "a6200000-0000-4000-8000-000000000009", "parentId": "a6100000-0000-4000-8000-000000000001", "nodeType": "hadith", "sourceLabel": "Hadith.—VIII", "sourceIdentifier": "VIII", "title": null, "sequenceIndex": 2, "startPageId": null, "endPageId": null}, {"id": "a6200000-0000-4000-8000-000000000010", "parentId": "a6100000-0000-4000-8000-000000000001", "nodeType": "hadith", "sourceLabel": "Hadith.—IX", "sourceIdentifier": "IX", "title": null, "sequenceIndex": 3, "startPageId": null, "endPageId": null}], "blocks": [{"id": "d0230000-0000-4000-8000-000000000001", "structuralNodeId": "a6200000-0000-4000-8000-000000000009", "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "saying, \"The comfort of my eyes is in salaat.\" This is an expression of his profound love for salaat. As Such, what else can be more valuable than salaat?", "rawOcrText": "Part I (a)—lmportance of Salaat 23 saying, \"The comfort of my eyes is in salaat.\" This is an ex- pression of his profound love for salaat. As Such, what else can be more valuable than salaat? Hadith.—vm IJS Hadhrat Ibn Mas''ood (Radhiyallaho anho) nafrates that he heard the Holy Prophet (Sallallaho alaihe wasallam) saying: \"At the approach of the hour of a salaat, van An el is deputed to roclaim, ''Arise, O Children of Aa am! and extinguisk the fire that you have (by com- mitting sins) kindled to burn yourselves. So, the people rise up, perform wudhu and offer their Zuhr prayer. This causes forgiveness of their sins committed since day-break. The same is repeated at Asr, Maghrib and Ishaa. After Ishaa people go to bed, but there are some who busy themselves in good, while some others in evil deeds. Hadhrat Salmagn (Radhiyallaho anho) says, \"After Ishaa the people get divided into three goups. There are some for whom the night is a source of blessing and gain. They are those who spend .it in the worship of Allah, while other people are asleep. For them the night brings geat reward from their Lord.'' There are others who turn their night into a burden and curse for themselves, for they in- dulge in various dark deeds in the dead of night. To them the night brings woe and misery. There is the third group of people who go to bed immediately after Ishaa; they neither gain nor lose.\" Hadith.—1X Jij J;..j Jj Jj u; ''{i y JWj", "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0230000-0000-4000-8000-000000000002", "structuralNodeId": "a6200000-0000-4000-8000-000000000009", "sequenceIndex": 1, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith.—VIII", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0230000-0000-4000-8000-000000000003", "structuralNodeId": "a6200000-0000-4000-8000-000000000009", "sequenceIndex": 2, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عَنْ ابْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ عَنْ رَسُولِ اللَّهِ ﷺ أَنَّهُ قَالَ يُبْعَثُ مُنَادٍ عِنْدَ حَضْرَةِ كُلِّ صَلَاةٍ فَيَقُولُ يَا بَنِي آدَمَ قُومُوا فَأَطْفِئُوا مَا أَوْقَدْتُمْ عَلَى أَنْفُسِكُمْ فَيَقُومُونَ فَيَتَطَهَّرُونَ وَيُصَلُّونَ الظُّهْرَ فَيُغْفَرُ لَهُمْ مَا بَيْنَهَا فَإِذَا حَضَرَتِ الْعَصْرُ فَمِثْلُ ذَلِكَ فَإِذَا حَضَرَ الْمَغْرِبُ فَمِثْلُ ذَلِكَ فَإِذَا حَضَرَتِ الْعَتَمَةُ فَمِثْلُ ذَلِكَ فَيَنَامُونَ فَمُدْلِجٌ فِي خَيْرٍ وَمُدْلِجٌ فِي شَرٍّ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0230000-0000-4000-8000-000000000004", "structuralNodeId": "a6200000-0000-4000-8000-000000000009", "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "رواه الطبراني في الكبير كذا في الترغيب", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0230000-0000-4000-8000-000000000005", "structuralNodeId": "a6200000-0000-4000-8000-000000000009", "sequenceIndex": 4, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Ibn Mas''ood (Radhiyallaho anho) narrates that he heard the Holy Prophet (Sallallaho alaihe wasallam) saying: \"At the approach of the hour of a salaat, an Angel is deputed to proclaim, ''Arise, O Children of Aadam! and extinguish the fire that you have (by committing sins) kindled to burn yourselves. So, the people rise up, perform wudhu and offer their Zuhr prayer. This causes forgiveness of their sins committed since day-break. The same is repeated at Asr, Maghrib and Ishaa. After Ishaa people go to bed, but there are some who busy themselves in good, while some others in evil deeds. Hadhrat Salmaan (Radhiyallaho anho) says, \"After Ishaa the people get divided into three groups. There are some for whom the night is a source of blessing and gain. They are those who spend it in the worship of Allah, while other people are asleep. For them the night brings great reward from their Lord.'' There are others who turn their night into a burden and curse for themselves, for they indulge in various dark deeds in the dead of night. To them the night brings woe and misery. There is the third group of people who go to bed immediately after Ishaa; they neither gain nor lose.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0230000-0000-4000-8000-000000000006", "structuralNodeId": "a6200000-0000-4000-8000-000000000010", "sequenceIndex": 5, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith.—IX", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0230000-0000-4000-8000-000000000007", "structuralNodeId": "a6200000-0000-4000-8000-000000000010", "sequenceIndex": 6, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عَنْ أَبِي قَتَادَةَ بْنِ رِبْعِيٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ قَالَ رَسُولُ اللَّهِ ﷺ قَالَ اللَّهُ تَبَارَكَ وَتَعَالَى إِنِّي افْتَرَضْتُ عَلَى أُمَّتِكَ خَمْسَ صَلَوَاتٍ وَعَهِدْتُ عِنْدِي عَهْدًا أَنَّهُ مَنْ جَاءَنِي يُحَافِظُ عَلَيْهِنَّ لِوَقْتِهِنَّ أَدْخَلْتُهُ الْجَنَّةَ وَمَنْ لَمْ يُحَافِظْ عَلَيْهِنَّ فَلَا عَهْدَ لَهُ عِنْدِي", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0230000-0000-4000-8000-000000000008", "structuralNodeId": "a6200000-0000-4000-8000-000000000010", "sequenceIndex": 7, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Jij J;..j Jj Jj u; ''{i y JWj", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}], "pageNumber": 23}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "c0240000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "sourceShowsPrintedPageLabel": true, "printedPageLabel": "24", "printedPageNumber": 24, "pdfPageNumber": 407, "sequenceIndex": 14, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true, "provenanceNotes": "Canonical transcription checked against the rendered secondary scan; master PDF page mapping retained. Fine vocalisation is preserved where clearly legible; no unresolved Arabic word or letter remains. English OCR correction and Arabic/translation-pair classification pass compared against the rendered source scan; raw OCR retained unchanged."}, "structuralNodes": [{"id": "a6000000-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "PART I", "sourceIdentifier": "I", "title": "IMPORTANCE OF SALAAT", "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "a6100000-0000-4000-8000-000000000001", "parentId": "a6000000-0000-4000-8000-000000000001", "nodeType": "chapter", "sourceLabel": "CHAPTER I", "sourceIdentifier": "I", "title": "THE REWARDS OF SALAAT", "sequenceIndex": 1, "startPageId": null, "endPageId": null}, {"id": "a6200000-0000-4000-8000-000000000010", "parentId": "a6100000-0000-4000-8000-000000000001", "nodeType": "hadith", "sourceLabel": "Hadith.—IX", "sourceIdentifier": "IX", "title": null, "sequenceIndex": 2, "startPageId": null, "endPageId": null}, {"id": "a6200000-0000-4000-8000-000000000011", "parentId": "a6100000-0000-4000-8000-000000000001", "nodeType": "hadith", "sourceLabel": "Hadith.—X", "sourceIdentifier": "X", "title": null, "sequenceIndex": 3, "startPageId": null, "endPageId": null}], "blocks": [{"id": "d0240000-0000-4000-8000-000000000001", "structuralNodeId": "a6200000-0000-4000-8000-000000000010", "sequenceIndex": 0, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "كذا في الدر المنثور برواية أبي داود وابن ماجه وفيه أيضا أخرج مالك وابن أبي شيبة وأحمد وأبو داود والنسائي وابن ماجه وابن حبان والبيهقي عن عبادة بن الصامت ذكر معنى حديث الباب مرفوعا بأطول منه", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0240000-0000-4000-8000-000000000002", "structuralNodeId": "a6200000-0000-4000-8000-000000000010", "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Abu. Qataadah bin Rab''iyy (Radhiyallaho anho) says, \"He heard the Prophet (Sallallaho alaihe wasallam) saying, Allah has said, \"O, Muhammad! I have ordained five times daily salaat for thy followers. I have made a covenant with myself that whosoever is regular in performing his salaat at its fixed hour, he shall be admitted into the Paradise. Those of thy followers who do not guard their salaat, are not included in this covenant. \" In another hadith, it is said that Allah has ordained five times salaat and whosoever is mindful of his salaat, by doing wudhu properly and by praying at fixed hours with sincerity and devotion, is assured by Allah of his entry into Paradise; and whosoever does not guard his salaat, there is no such guarantee for him; he. may—or may not be forgiven. salaat has indeed a tremendous value. It affords us an opportunity to receive Allah''s guarantee for Paradise. When an honourable person of some financial standing or having executive power gives us a guarantee or stands surety for meeting any of our requirements of this world, we feel quite satisfied and happy and we consider it our duty to remain obliged and devoted to him. Here Allah,the Absolute Sovereign of both the worlds, is giving the guarantee and is standing surety for the real success after death in return for five times daily salaat, which does not involve much effort on our part. If even then we do not avail of the opportunity, we shall have none to blame, but ourselves for the dreadful doom that awaits us.", "rawOcrText": "24 Virtues-of Salaat 4.*I.a 4.''rb Hadhrat Abu. Qataadah bin Rab''iyy (Radhiyallaho anho) says, \"He heard the Prophet (Sallallaho alaihe wasallam) saying, Allah has said, \"O, Muhammad! I have ordained five times daily salaat for thy followers. I have made a covenant with myself that whosoever is regular in performing his salaat at its fixed hour, he shall be admitted into the Paradisev Those of thy föl• lowers who do not guard their salaat, are not included in this covenant. \" .1n another hadith, it is said that Allah has ordained five times salaat and whosoever is mindful of his salaat, by doing wudhu properly and by praying at fixed hours with sincerity and devotion, is assured by Allah of his entry into Paradise; and whosoever does not guard his salaat, there is no such guarantee for him; he. may—or may not be forgiven. salaat has indeed a tremendous value. Jt affords us an op- portunity to receive Allah''s guarantee for Paradise. When an honourable person of some financial standing or having executive power gives us a guarantee or stands surety for meeting any of our requirements of this world, we feel quite satisfied and happy and we consider it our duty to remain obliged and devoted to him. Here Allah,the Abso- lute Sovereign of both the worlds, is giving the guarantee and is standing surety for the real success after death in return for five times daily salaat, which does not involve much effort on our part. If even then we do not avail of the opportunity, we shall have none to blame, but ourselves for the dreadful doom that awaits us. Hadith—X", "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0240000-0000-4000-8000-000000000003", "structuralNodeId": "a6200000-0000-4000-8000-000000000011", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith.—X", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}, {"id": "d0240000-0000-4000-8000-000000000004", "structuralNodeId": "a6200000-0000-4000-8000-000000000011", "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عَنْ ابْنِ سَلْمَانَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَجُلًا مِنْ أَصْحَابِ النَّبِيِّ ﷺ حَدَّثَهُ قَالَ لَمَّا فَتَحْنَا خَيْبَرَ أَخْرَجُوا غَنَائِمَهُمْ مِنَ الْمَتَاعِ وَالسَّبْيِ فَجَعَلَ النَّاسُ يَتَبَايَعُونَ غَنَائِمَهُمْ فَجَاءَ رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ لَقَدْ رَبِحْتُ رِبْحًا مَا رَبِحَ الْيَوْمَ مِثْلَهُ أَحَدٌ مِنْ أَهْلِ هَذَا الْوَادِي فَقَالَ وَيْحَكَ وَمَا رَبِحْتَ قَالَ مَا زِلْتُ أَبِيعُ وَأَبْتَاعُ حَتَّى رَبِحْتُ ثَلَاثَمِائَةِ أُوقِيَّةٍ فَقَالَ رَسُولُ اللَّهِ ﷺ أَنَا أُنَبِّئُكَ بِخَيْرِ رَجُلٍ رَبِحَ قَالَ مَا هُوَ يَا رَسُولَ اللَّهِ قَالَ رَكْعَتَيْنِ بَعْدَ الصَّلَاةِ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review"}], "pageNumber": 24}'::jsonb);
